/// <summary>
/// Data contract class for service <c>METSendPricingHeaderContract</c>
/// </summary>
[DataContractAttribute]
public class METSendPricingHeaderContract
{

    DataAreaId               dataAreaId;
    METExternalOrderNumber   externalPEorderId;
    CustAccount              custAccount;
    SalesId                  salesId;

}

Method.Source:
/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Parameter method for METExternalOrderNumber
/// </summary>
/// <param name = "_externalPEorderId">externalOrderNumber</param>
/// <returns>externalOrdernumber</returns>
[DataMemberAttribute('ExternalPEorderId')]
public METExternalOrderNumber parmExternalOrderId(METExternalOrderNumber _externalPEorderId = externalPEorderId)
{
    externalPEorderId  = _externalPEorderId;
    return externalPEorderId;
}

/// <summary>
/// Parameter method for CustomerId
/// </summary>
/// <param name = "_custAccount">customerId</param>
/// <returns>custAccount</returns>
[DataMemberAttribute('CustomerId')]
public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount  = _custAccount;
    return custAccount;
}

/// <summary>
/// Parameter method for SalesId
/// </summary>
/// <param name = "_salesId">salesId</param>
/// <returns>SalesId</returns>
[DataMemberAttribute('SalesId')]
public SalesId parmSalesId(SalesId _salesId = SalesId)
{
    salesId  = _salesId;
    return salesId;
}

/// <summary>
/// Instantiate new object
/// </summary>
/// <returns>The new object</returns>
public static METSendPricingHeaderContract construct()
